<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';
import App from '../../../../App.vue';
import WorkBreakControl from '../../../../components/WorkBreakControl.vue';
const NAV=Object.freeze([{id:'Work',label:'Work',icon:'⌂'},{id:'Performance',label:'Performance',icon:'◈'},{id:'Timeline',label:'Timeline',icon:'◷'},{id:'Admin',label:'Admin',icon:'▦'}]);
const route=ref(location.hash.slice(1)||'Work');const online=ref(typeof navigator==='undefined'?true:navigator.onLine);const darkMode=ref(true);const menuOpen=ref(false);const showWorkBreak=ref(route.value==='Work'||route.value==='');const reducedMotion=ref(false);const ambientLightAvailable=ref(false);const driverState=ref('DAY_START');
const activeNav=computed(()=>NAV.some(item=>item.id===route.value)?route.value:'Work');const fuelVisible=computed(()=>['Work','Performance','Timeline'].includes(activeNav.value));
const stateMeta=computed(()=>{if(!online.value)return{label:'Offline',className:'offline'};const states={DAY_START:{label:'Ready to start the day',className:'waiting'},DAY_READY:{label:'Day Ready',className:'waiting'},SHIFT_WAITING:{label:'Shift Waiting',className:'waiting'},BUSINESS_TRIP:{label:'On Business Trip',className:'business'},PERSONAL_TRIP:{label:'Personal trip',className:'personal'},DAY_ENDED:{label:'Day Ended',className:'waiting'}};return states[String(driverState.value||'DAY_START').toUpperCase()]||states.DAY_START});
const headerContextLabel=computed(()=>activeNav.value==='Work'?'Kanishka Enterprises':activeNav.value);
function syncRoute(){route.value=location.hash.slice(1)||'Work';showWorkBreak.value=route.value==='Work'||route.value==='';menuOpen.value=false}function navigate(path){const next=String(path||'Work');if(location.hash.slice(1)===next){syncRoute();return}location.hash=next}function goBack(){if(history.length>1)history.back();else navigate('Work')}function vibrate(pattern=10){try{navigator.vibrate?.(pattern)}catch{}}function openSettings(){navigate('Settings');menuOpen.value=false;vibrate(8)}function toggleMenu(){menuOpen.value=!menuOpen.value;vibrate(8)}function openFuel(){if(!fuelVisible.value)return;window.dispatchEvent(new CustomEvent('kfe:toggle-fuel'));vibrate(8)}function setTheme(nextDark){darkMode.value=nextDark;document.documentElement.dataset.kfeTheme=nextDark?'dark':'light'}function restoreTheme(){const media=globalThis.matchMedia?.('(prefers-color-scheme: dark)');setTheme(media?media.matches:true)}function detectAmbientLight(){ambientLightAvailable.value='AmbientLightSensor' in globalThis;if(!ambientLightAvailable.value)return;try{const sensor=new AmbientLightSensor({frequency:1});sensor.addEventListener('reading',()=>{if(sensor.illuminance<25)setTheme(true);else if(sensor.illuminance>500)setTheme(false)});sensor.start()}catch{ambientLightAvailable.value=false}}function handleOnline(){online.value=true}function handleOffline(){online.value=false}function handleDriverState(event){driverState.value=event?.detail?.state||'DAY_START'}function handleKeydown(event){if(event.key==='Escape')menuOpen.value=false}
onMounted(()=>{window.addEventListener('hashchange',syncRoute);window.addEventListener('online',handleOnline);window.addEventListener('offline',handleOffline);window.addEventListener('kfe:swipe-state',handleDriverState);window.addEventListener('keydown',handleKeydown);reducedMotion.value=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches??false;restoreTheme();detectAmbientLight()});onUnmounted(()=>{window.removeEventListener('hashchange',syncRoute);window.removeEventListener('online',handleOnline);window.removeEventListener('offline',handleOffline);window.removeEventListener('kfe:swipe-state',handleDriverState);window.removeEventListener('keydown',handleKeydown)});
</script>
<template><div class="driver-shell" :data-online="online" :data-reduced-motion="reducedMotion"><header class="driver-header" aria-label="KFE driver shell"><div class="header-left"><button class="header-button" type="button" aria-label="Open shell menu" :aria-expanded="menuOpen" @click="toggleMenu">☰</button><button v-if="fuelVisible" class="header-button fuel-button" type="button" aria-label="Quick fuel" @click="openFuel">⛽</button></div><div class="header-context"><strong>{{headerContextLabel}}</strong></div><div class="header-state" :class="`state-${stateMeta.className}`"><i aria-hidden="true"></i><b>{{stateMeta.label}}</b></div></header>
<aside v-if="menuOpen" class="shell-menu" aria-label="Shell controls"><div class="menu-title">SHELL</div><button type="button" @click="setTheme(true);menuOpen=false;vibrate(8)"><span>◐</span><b>Dark mode</b><em v-if="darkMode">ACTIVE</em></button><button type="button" @click="setTheme(false);menuOpen=false;vibrate(8)"><span>○</span><b>Light mode</b><em v-if="!darkMode">ACTIVE</em></button><div class="menu-divider"></div><div class="menu-title">DATA SAFETY</div><button type="button" @click="openSettings"><span>⇅</span><b>Backup & restore</b><em>OPEN</em></button><button type="button" @click="openSettings"><span>⌫</span><b>Reset local data</b><em>OPEN</em></button><div class="menu-divider"></div><button type="button" @click="goBack();menuOpen=false;vibrate(10)"><span>‹</span><b>Back</b></button><p v-if="!online" class="offline-note">No connection. The app remains available for local work.</p></aside>
<main class="driver-content"><div class="content-surface"><App /></div></main><nav class="quick-dock" aria-label="Primary driver navigation"><button v-for="item in NAV" :key="item.id" type="button" :class="{active:activeNav===item.id}" :aria-current="activeNav===item.id?'page':undefined" @click="navigate(item.id);vibrate(8)"><span class="dock-icon">{{item.icon}}</span><strong>{{item.label}}</strong></button></nav><div class="system-status"><span v-if="ambientLightAvailable">AUTO LIGHT</span></div><WorkBreakControl v-if="showWorkBreak" /></div></template>
<style scoped>
