rsonal{color:#3B82F6}.state-offline{color:var(--shell-text)}.shell-menu{position:fixed;z-index:13000;top:calc(82px + env(safe-area-inset-top));left:12px;width:min(310px,calc(100vw - 24px));max-height:calc(100dvh - 94px - env(safe-area-inset-top));overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;touch-action:pan-y;padding:12px;border:1px solid var(--shell-border);border-radius:22px;background:rgba(16,20,25,.96);box-shadow:0 22px 60px rgba(0,0,0,.42);backdrop-filter:blur(20px)}.menu-title{padding:8px 10px 6px;color:var(--shell-muted);font-size:.65rem;font-weight:900;letter-spacing:.14em}.shell-menu button{width:100%;min-height:56px;padding:0 12px;display:grid;grid-template-columns:28px 1fr auto;align-items:center;gap:8px;border:0;border-radius:14px;background:transparent;color:var(--shell-text);font:inherit;text-align:left;touch-action:manipulation;-webkit-tap-highlight-color:transparent}.shell-menu button:focus-visible{background:var(--shell-surface-2);outline:none}.shell-menu button span{text-align:center}.shell-menu button em{color:var(--shell-accent);font-size:.62rem;font-style:normal;font-weight:950}.menu-divider{height:1px;margin:8px 4px;background:var(--shell-border)}.offline-note{margin:10px 8px 4px;color:var(--shell-muted);font-size:.72rem}.driver-content{height:100dvh;min-height:100dvh;padding-top:calc(76px + env(safe-area-inset-top));padding-bottom:calc(96px + env(safe-area-inset-bottom));overflow:hidden}.content-surface{width:100%;height:100%;min-height:0;overflow:hidden}:deep(.kfe-topbar),:deep(.kfe-bottom-nav){display:none!important}:deep(.kfe-shell){min-height:0!important;height:100%!important;background:transparent!important;overflow:hidden}:deep(.kfe-viewport){min-height:0!important;height:100%!important;overflow:hidden!important}:deep(.kfe-workspace){padding-bottom:0!important;min-height:0!important}.quick-dock{position:fixed;z-index:12000;left:10px;right:10px;bottom:calc(10px + env(safe-area-inset-bottom));min-height:78px;padding:7px;display:grid;grid-template-columns:repeat(4,1fr);gap:6px;border:1px solid var(--shell-border);border-radius:24px;background:rgba(16,20,25,.86);box-shadow:0 18px 50px rgba(0,0,0,.38);backdrop-filter:blur(18px)}.quick-dock button{min-width:0;min-height:64px;border:0;border-radius:18px;background:transparent;color:var(--shell-muted);display:grid;place-items:center;align-content:center;gap:2px;font:inherit;touch-action:manipulation}.quick-dock button.active{color:var(--shell-accent);background:rgba(94,230,168,.13)}.dock-icon{font-size:1.35rem}.quick-dock strong{font-size:.68rem;font-weight:900}.system-status{position:fixed;z-index:11900;left:16px;bottom:calc(102px + env(safe-area-inset-bottom));pointer-events:none;color:var(--shell-muted);font-size:.62rem;font-weight:850}@media(min-width:760px){.quick-dock{left:50%;right:auto;transform:translateX(-50%);width:min(680px,calc(100vw - 28px))}}@media(max-width:560px){.header-button{width:52px;height:52px;min-width:52px}.header-state{padding:0 2px;font-size:.62rem}.header-state b{max-width:84px;overflow:hidden;text-overflow:ellipsis}.header-context strong{font-size:.82rem}}@media(prefers-reduced-motion:reduce){.driver-shell *,.driver-shell *::before,.driver-shell *::after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
